/**
 * A class's icon, and the purpose that colours it.
 *
 * The data is `classIconData.ts`, generated by `npm run build:icons`; this is
 * how the editor and the documentation read it. Both draw an icon from the
 * same markup, so a class looks the same in the type picker, the DataModel
 * panel and the docs' drawings of either.
 *
 * ## Filled and outline at once
 *
 * The markup holds both, as `.ci-f` and `.ci-o`, and the stylesheet shows the
 * one Settings › Class icons asks for. The setting is then a root attribute
 * rather than something every list has to be told, and a docs page drawn
 * before the reader changed it still follows it.
 *
 * ## Colour
 *
 * `var(--purpose-<id>)`, a shade for dark schemes and one for light: see
 * `derivedTokens`. A datatype whose wire has a colour of its own wears that
 * instead, so its icon matches its pins.
 */

import { CLASS_ICONS, ICON_BODIES, NO_ICON, TYPE_ICONS } from "./classIconData.js";
import { PURPOSE_ORDER, PURPOSES, type Purpose } from "./classIconPurposes.js";

export { PURPOSE_ORDER, PURPOSES, type Purpose };

export interface ClassIcon {
	purpose: Purpose;
	/** Which markup, for `classIconMarkup`. */
	body: number;
}

/** An engine class's icon, or undefined for a script class or a name the catalogue does not hold. */
export function classIconOf(name: string): ClassIcon | undefined {
	const entry = Object.hasOwn(CLASS_ICONS, name) ? CLASS_ICONS[name] : undefined;
	return entry && { purpose: PURPOSE_ORDER[entry[0]], body: entry[1] };
}

/** A Roblox datatype's icon, or undefined for one without. */
export function typeIconOf(name: string): ClassIcon | undefined {
	const entry = Object.hasOwn(TYPE_ICONS, name) ? TYPE_ICONS[name] : undefined;
	return entry && { purpose: PURPOSE_ORDER[entry[0]], body: entry[1] };
}

/** The icon for a name with none of its own: grey, a question in a box. */
export const NO_CLASS_ICON: ClassIcon = { purpose: "studio", body: NO_ICON };

/** The heading a class sits under when classes are grouped by purpose. */
export function purposeLabel(purpose: Purpose): string {
	return PURPOSES[purpose][0];
}

/** The custom property that colours a purpose's icons. */
export function purposeColor(purpose: Purpose): string {
	return `var(--purpose-${purpose})`;
}

const VIEW = 'x="0" y="-960" width="960" height="960"';

/** One style's layers: under, cut out of it by a mask, then over. */
function layered([under, cut = "", over = ""]: readonly string[], mask: string): string {
	if (!cut) return under + over;
	return (
		`<mask id="${mask}" maskUnits="userSpaceOnUse" ${VIEW}>` +
		`<rect ${VIEW} fill="white"/><g fill="black" style="color:black">${cut}</g></mask>` +
		`<g mask="url(#${mask})">${under}</g>${over}`
	);
}

/**
 * An icon's inner SVG markup, for an `<svg viewBox="0 -960 960 960">` with
 * `fill="currentColor"`. `id` must be unique in the document: a cut is a mask,
 * and a mask is found by its id.
 */
export function classIconMarkup(body: number, id: string): string {
	const [filled, outline] = ICON_BODIES[body] ?? ICON_BODIES[NO_ICON];
	if (!outline) return layered(filled, `${id}f`);
	return `<g class="ci-f">${layered(filled, `${id}f`)}</g><g class="ci-o">${layered(outline, `${id}o`)}</g>`;
}
